-- Build 9.2: Aufgabenkatalog erweitert (Zeichnen, Fun, Quiz, Pantomime, Erklären) + Event-Texte aus Tabelle
create table if not exists public.party_event_texts(
 id serial primary key,
 effect text not null check (effect in ('plus','minus')),
 text text not null unique
);
alter table public.party_event_texts enable row level security;

create or replace function public.party_pick_event(p_plus boolean) returns text
language sql volatile security definer set search_path='' as $f$
 select text from public.party_event_texts where effect=case when p_plus then 'plus' else 'minus' end order by random() limit 1
$f$;

-- party_action: hart codierte Event-Arrays durch Tabellenabfrage ersetzen
do $do$
declare d text;
begin
 d:=pg_get_functiondef('public.party_action(text,uuid,uuid,text)'::regprocedure);
 if d like '%party_pick_event%' then return; end if;
 d:=regexp_replace(d,'event_text:=case when effect>0 then \(array\[.*?\]\)\[floor\(random\(\)\*8\)::int\+1\] else \(array\[.*?\]\)\[floor\(random\(\)\*8\)::int\+1\] end;','event_text:=public.party_pick_event(effect>0);');
 if d not like '%party_pick_event%' then raise exception 'Event-Patch nicht angewendet'; end if;
 execute d;
end $do$;

on conflict (text) do nothing;

select k,t from (
